import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Procedures in AL","description":"","frontmatter":{},"headers":[],"relativePath":"procedures/index.md","filePath":"procedures/index.md"}`),a={name:`procedures/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="procedures-in-al" tabindex="-1">Procedures in AL <a class="header-anchor" href="#procedures-in-al" aria-label="Permalink to “Procedures in AL”">​</a></h1><p>A <strong>procedure</strong> is a named, reusable block of code that performs a specific task. Procedures help us organize code, avoid repetition, and make programs easier to understand and maintain.</p><p>For example, instead of calculating a product&#39;s price directly inside <code>OnOpenPage()</code>, we can create a procedure called <code>CalculateTotalPrice()</code> and call it whenever we need the calculation.</p><h2 id="declaring-and-calling-procedures" tabindex="-1">Declaring and Calling Procedures <a class="header-anchor" href="#declaring-and-calling-procedures" aria-label="Permalink to “Declaring and Calling Procedures”">​</a></h2><p>Use the <code>procedure</code> keyword to declare a procedure.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure GreetUser()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Welcome to Business Central!&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>To execute the procedure, call it by name:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>trigger OnOpenPage()</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    GreetUser();</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here is a more complete example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace LearningAl;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    local procedure GreetUser()</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Welcome to Business Central&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    trigger OnOpenPage();</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        GreetUser();</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>Key points:</strong></p><ul><li>A procedure declaration contains its name, optional parameters, and an optional return type.</li><li>The <code>begin</code> and <code>end</code> keywords enclose the procedure&#39;s body.</li><li>Calling a procedure executes its body.</li><li>Parentheses are used when calling a procedure, even when it takes no parameters.</li><li>Procedures can be declared inside AL objects, such as pages, page extensions, and codeunits.</li></ul><h2 id="parameters-and-return-values" tabindex="-1">Parameters and Return Values <a class="header-anchor" href="#parameters-and-return-values" aria-label="Permalink to “Parameters and Return Values”">​</a></h2><h3 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h3><p>Parameters allow us to pass information into a procedure, making it reusable with different inputs.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure GreetUser(UserName: Text)</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Welcome, %1!&#39;, UserName);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Call the procedure with an argument:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GreetUser(&#39;Dennis&#39;);</span></span>
<span class="line"><span>GreetUser(&#39;Alice&#39;);</span></span></code></pre></div><p>The procedure receives the supplied text through its <code>UserName</code> parameter.</p><p>When declaring multiple parameters, separate them with semicolons. When calling the procedure, separate the arguments with commas.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure AddNumbers(FirstNumber: Integer; SecondNumber: Integer)</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Message(&#39;Sum: %1&#39;, FirstNumber + SecondNumber);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Call it:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AddNumbers(10, 20);</span></span></code></pre></div><h3 id="return-values" tabindex="-1">Return Values <a class="header-anchor" href="#return-values" aria-label="Permalink to “Return Values”">​</a></h3><p>A procedure can return a value to the code that called it.</p><p>Declare the return type after the parameter list.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure AddNumbers(FirstNumber: Integer; SecondNumber: Integer): Integer</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    exit(FirstNumber + SecondNumber);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Use the returned value:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    Result: Integer;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Result := AddNumbers(10, 20);</span></span>
<span class="line"><span>    Message(&#39;Result: %1&#39;, Result);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Here, <code>: Integer</code> declares the return type, and <code>exit()</code> returns the calculated result.</p><p>A procedure without a declared return type performs an operation without returning a value.</p><h2 id="local-versus-global-procedures" tabindex="-1">Local Versus Global Procedures <a class="header-anchor" href="#local-versus-global-procedures" aria-label="Permalink to “Local Versus Global Procedures”">​</a></h2><p>AL procedures can have different levels of accessibility.</p><h3 id="local-procedures" tabindex="-1">Local Procedures <a class="header-anchor" href="#local-procedures" aria-label="Permalink to “Local Procedures”">​</a></h3><p>A local procedure is declared using the <code>local</code> keyword.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure CalculateDiscount(Price: Decimal): Decimal</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    exit(Price * 0.10);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>A local procedure can be called from other code within the same AL object, subject to the normal scope rules, but not directly from another AL object.</p><p>Use local procedures for implementation details that should remain inside their object.</p><h3 id="global-procedures" tabindex="-1">Global Procedures <a class="header-anchor" href="#global-procedures" aria-label="Permalink to “Global Procedures”">​</a></h3><p>A procedure declared without the <code>local</code> keyword is traditionally described as a global procedure.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>procedure CalculateDiscount(Price: Decimal): Decimal</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    exit(Price * 0.10);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>A global procedure is potentially accessible to code outside its object, subject to AL&#39;s accessibility rules and the object&#39;s context.</p><p><strong>Important:</strong> Omitting <code>local</code> does not mean every other object can automatically call the procedure. Accessibility depends on factors such as the object type, procedure exposure, and applicable AL rules.</p><p>Use local procedures by default when the functionality does not need to be exposed externally.</p><h2 id="passing-parameters-by-value-and-by-reference" tabindex="-1">Passing Parameters by Value and by Reference <a class="header-anchor" href="#passing-parameters-by-value-and-by-reference" aria-label="Permalink to “Passing Parameters by Value and by Reference”">​</a></h2><p>AL supports two ways of passing parameters: <strong>by value</strong> and <strong>by reference</strong>.</p><h3 id="passing-by-value" tabindex="-1">Passing by Value <a class="header-anchor" href="#passing-by-value" aria-label="Permalink to “Passing by Value”">​</a></h3><p>By default, parameters are passed by value. The procedure receives a copy of the supplied value.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure IncreaseNumber(Number: Integer)</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Number := Number + 10;</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    MyNumber: Integer;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    MyNumber := 5;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    IncreaseNumber(MyNumber);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Message(&#39;Number: %1&#39;, MyNumber);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>The result is <code>5</code>, not <code>15</code>, because changing the procedure&#39;s parameter does not change the caller&#39;s integer variable.</p><h3 id="passing-by-reference" tabindex="-1">Passing by Reference <a class="header-anchor" href="#passing-by-reference" aria-label="Permalink to “Passing by Reference”">​</a></h3><p>Use the <code>var</code> keyword before a parameter&#39;s name to pass it by reference.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure IncreaseNumber(var Number: Integer)</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Number := Number + 10;</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    MyNumber: Integer;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    MyNumber := 5;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    IncreaseNumber(MyNumber);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Message(&#39;Number: %1&#39;, MyNumber);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>The result is <code>15</code> because the procedure modifies the original variable.</p><p><strong>When should you use <code>var</code>?</strong></p><ul><li>When the procedure must modify a caller&#39;s variable.</li><li>When you want to return a result through an existing variable rather than through the procedure&#39;s return value.</li></ul><p>Use <code>var</code> only when the procedure needs to modify the supplied variable. It makes the side effect explicit.</p><h2 id="returning-values-with-exit" tabindex="-1">Returning Values with <code>exit</code> <a class="header-anchor" href="#returning-values-with-exit" aria-label="Permalink to “Returning Values with exit”">​</a></h2><p>In AL, <code>exit</code> serves two important purposes:</p><ul><li>It immediately exits the current procedure or trigger.</li><li>In a procedure that declares a return type, <code>exit(Value)</code> returns a value to the caller and stops execution of that procedure.</li></ul><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>local procedure GetDiscount(Price: Decimal): Decimal</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    if Price &gt;= 1000 then</span></span>
<span class="line"><span>        exit(Price * 0.15);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    exit(Price * 0.05);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>The procedure returns a discount of 15% when the price is at least 1,000; otherwise, it returns 5%.</p><p>Once an <code>exit(Value)</code> statement executes, the procedure stops. Any statements after that executed branch are not reached.</p><p><strong>Important:</strong> If a procedure returns a value, ensure every possible execution path returns an appropriate result. Do not rely on an implicit default value to represent a meaningful business result.</p><h2 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to “Additional Resources”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/training/modules/create-custom-functions/" target="_blank" rel="noreferrer">Microsoft Learn: Create custom procedures in AL</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-methods" target="_blank" rel="noreferrer">Microsoft Learn: Working with AL methods</a></li></ul>`,71)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};